import{_ as a,c as t,a7 as r,o as s}from"./chunks/framework.D10gHr3F.js";const g=JSON.parse('{"title":"ESA Openscapes Champions Lessons","description":"","frontmatter":{},"headers":[],"relativePath":"Training and Resources/openscapes.md","filePath":"Training and Resources/openscapes.md"}'),o={name:"Training and Resources/openscapes.md"};function n(i,e,p,l,c,h){return s(),t("div",null,e[0]||(e[0]=[r('<h1 id="esa-openscapes-champions-lessons" tabindex="-1">ESA Openscapes Champions Lessons <a class="header-anchor" href="#esa-openscapes-champions-lessons" aria-label="Permalink to &quot;ESA Openscapes Champions Lessons&quot;">​</a></h1><p>In spring 2026, ESA partnered with Openscapes to lead a 10–week Champions Cohort to explore open data science practices to help participants experiment and plan FAIR principles for Earth Observation and EarthCODE. This is a short overview of the lessons; please see [ TODO LINK TO EARTHCODE BLOG POST ] to learn about what participants did and accomplished.</p><p>The ESA Champions Cohort taught the following lessons with CC-By license, available for self-paced learning resources, and to reuse and remix. They are a combination of Openscapes core lessons and new lessons developed by Lampata: FAIR strategies and EarthCODE.</p><table tabindex="0"><thead><tr><th>Cohort Call Topics</th><th>Slides</th></tr></thead><tbody><tr><td>1. Openscapes mindset</td><td><a href="https://docs.google.com/presentation/d/1fXgrWU5AMrZwgvpjs2J0dRT9x1Tc-IZyQIn8yPZSGM8/" target="_blank" rel="noreferrer">mindset</a>, <a href="https://docs.google.com/presentation/d/13rZnx2ybgKIYlN36ugCPH0e2RfaiQefxwmhv5F_mfqc/" target="_blank" rel="noreferrer">better science for future us</a> (<a href="https://youtu.be/FfpA_Ja8xPw" target="_blank" rel="noreferrer">recording</a>)</td></tr><tr><td>2. GitHub for publishing &amp; project management</td><td><a href="https://openscapes.github.io/series/github-pub" target="_blank" rel="noreferrer">publishing</a>, <a href="https://openscapes.github.io/series/github-issues" target="_blank" rel="noreferrer">project management</a> (<a href="https://docs.google.com/presentation/d/1geUN-dv-NMx6IgeCwMRVmTO8nZaauIl26tZDOrkLW_E/" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>3. Team culture and data strategies for future us</td><td><a href="https://docs.google.com/presentation/d/1TwCyf9xicLWBfPhW9HnYQH3-mHycEyVKTm38zSg4D3Q/" target="_blank" rel="noreferrer">team culture</a>, <a href="https://docs.google.com/presentation/d/1CgpNio4tdP04cVWxCnGvqbT24ih9slXStP8T8RjPIAc/" target="_blank" rel="noreferrer">data strategies</a></td></tr><tr><td>4. Open communities and coding strategies for future us</td><td><a href="https://docs.google.com/presentation/d/1u6AjCCKniDsuX10M-qAU2O1HLJqupDYhWWKZYfeCpK4/" target="_blank" rel="noreferrer">open communities</a>, <a href="https://docs.google.com/presentation/d/1GYNPRVn9g1cP0YwdbAc_aoPsra1H8bpKlTprSOekorQ/" target="_blank" rel="noreferrer">FAIR strategies and EarthCODE</a> (<a href="https://youtu.be/ftcmAVyJLAs" target="_blank" rel="noreferrer">recording</a>)</td></tr><tr><td>5. Pathways share and next steps</td><td><a href="https://openscapes.github.io/series/core-lessons/pathways" target="_blank" rel="noreferrer">pathways</a></td></tr></tbody></table><h2 id="more-about-openscapes-and-the-champions-program" tabindex="-1">More about Openscapes and the Champions program: <a class="header-anchor" href="#more-about-openscapes-and-the-champions-program" aria-label="Permalink to &quot;More about Openscapes and the Champions program:&quot;">​</a></h2><ul><li><a href="https://openscapes.github.io/series/" target="_blank" rel="noreferrer"><strong>Openscapes Champions Lesson Series</strong></a> - This hosts details about the Champions program as well as open lesson materials and recordings.</li><li><a href="https://www.nature.com/articles/s41559-017-0160" target="_blank" rel="noreferrer"><strong>Our path to better science in less time using open data science tools</strong></a> (Lowndes et al. 2017) - This describes a marine science team’s transition to open collaborative teamwork. It was the original inspiration for creating the Champions Program and heavily influences the Core Lessons. We’ll ask that everyone participating reads it before our first Cohort Call.</li><li><a href="https://openscapes.github.io/supercharge-research/" target="_blank" rel="noreferrer"><strong>Supercharge your research: a ten-week plan for open data science</strong></a> (Lowndes et al. 2019) - This was co-authored with the inaugural Champions Cohort, capturing the most valuable take-aways for marine and environmental science early career faculty.</li><li><a href="https://onlinelibrary.wiley.com/doi/10.1002/ece3.11341" target="_blank" rel="noreferrer"><strong>Shifting institutional culture to develop climate solutions with Open Science</strong></a> (Lowndes et al. 2024) - This was co-authored by Openscapes mentors across organizations – including NASA Earthdata, NOAA Fisheries, EPA, California Water Boards, Pathways to Open Science, Fred Hutch Cancer Center.</li></ul>',6)]))}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
